    con.executescript(SCHEMA)
    con.executescript(open(path, encoding="utf-8").read())
    return con


def guarded(con, sql, seconds=10):
    t0 = time.time()
    con.set_progress_handler(lambda: 1 if time.time() - t0 > seconds else 0, 100000)
